/**
 * The consumer's shadcn flavor file, `clossys/components.json`: the Designer's shadcn flavor (style, iconLibrary,
 * aliases) every pinned Designer component renders in, generated by the Designer's one components.json writer
 * (`@clossys/designer/shadcn-flavor`) with the consumer's stylesheet. ref-verbatim and code adopt normalize stock
 * items against it.
 *
 * Its writers are the build step (scripts/check-generated-derived.mjs --write, which re-exports these functions and
 * checks the stored file against `flavorJson`) and `clossys config --init` (cli/owner.ts), so a consumer workspace
 * gets the same file the build writes. Nothing else spells a components.json.
 */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join, relative, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";
import { shadcnComponentsJsonText } from "@clossys/designer/shadcn-flavor";
import { PRODUCER_ROOT } from "../package-path.js";

/** The flavor file's path in a consumer workspace, relative to the workspace root. */
export const FLAVOR_FILE = "clossys/components.json";

/**
 * The stylesheet the consumer's pinned components render in, relative to clossys/: the Studio's,
 * which imports the Designer ui styles and the generated flow theme. shadcn writes theme variables
 * into `tailwind.css`, so it must name a file that exists.
 */
export const CONSUMER_STYLESHEET = "../packages/producer/studio/styles/studio.css";

const posix = (path: string): string => path.split(sep).join("/");

/**
 * The stylesheet a consumer's shadcn flavor file names, relative to the consumer's folder. A
 * Foundry checkout keeps the Studio's, read where it is (CONSUMER_STYLESHEET for a clossys/ at the
 * repository root, the same file from the fixture consumer's folder). An installed Producer ships no
 * Studio, so a packed consumer names the installed Designer theme (`@clossys/designer/theme.css`):
 * never a path that exists only in the Foundry repository.
 */
export function consumerStylesheet(clossysRoot: string): string {
  const studio = join(PRODUCER_ROOT, "studio", "styles", "studio.css");
  if (existsSync(studio)) return posix(relative(resolve(clossysRoot), studio));
  return posix(relative(clossysRoot, fileURLToPath(import.meta.resolve("@clossys/designer/theme.css"))));
}

/**
 * clossys/components.json: the Designer's shadcn flavor, the one every pinned Designer component
 * renders in, generated by the Designer's own writer with the consumer's stylesheet.
 */
export function flavorJson(css: string = CONSUMER_STYLESHEET): string {
  return shadcnComponentsJsonText({ css });
}

/**
 * Write the consumer's shadcn flavor file; returns whether it changed. `at` is the consumer folder the file will be read
 * from (the stylesheet path is relative to it): the folder itself, unless a seeder writes it in a staging root.
 * A file that already holds the flavor is left as it is; any other is brought to the flavor (it is generated, never
 * hand-written).
 */
export function writeFlavor(clossysRoot: string, at: string = clossysRoot): boolean {
  const path = join(clossysRoot, "components.json"), content = flavorJson(consumerStylesheet(at));
  if (existsSync(path) && readFileSync(path, "utf8") === content) return false;
  writeFileSync(path, content);
  return true;
}
